import { Table } from "march/table"

// atıştırmalık tablosu: başlığa tıkla, kaloriye ya da ada göre sırala; arama kutusu süzer
const SNACKS = [
  { ad: "🍎 Elma", kalori: 52, tat: "tatlı" }, { ad: "🥨 Simit", kalori: 280, tat: "tuzlu" }, { ad: "🍫 Çikolata", kalori: 546, tat: "tatlı" },
  { ad: "🥜 Fıstık", kalori: 567, tat: "tuzlu" }, { ad: "🥕 Havuç", kalori: 41, tat: "tatlı" }, { ad: "🧀 Peynir", kalori: 402, tat: "tuzlu" },
]

export function Snacks() {
  return <Table rows={SNACKS} rowKey="ad" caption="Atıştırmalıklar" paging={false} columns={[
    { key: "ad", label: "Atıştırmalık" },
    { key: "kalori", label: "Kalori (100 g)", align: "end", format: "number" },
    { key: "tat", label: "Tat", filter: "select", options: ["tatlı", "tuzlu"] },
  ]} />
}

import { Table } from "march/table"
import { Avatar, Badge, Rating, action } from "march/ui"
import { mail, trash } from "march/icons"

// üye yönetimi: 10.000 satır sanal kaydırmayla akar; sırala (Shift ile çoklu), şehre ve duruma göre süz, seç,
// toplu davet / askıya alma, CSV indir
const FIRST = ["Elif", "Mert", "Zeynep", "Can", "Ayşe", "Emre", "Selin", "Burak", "Ece", "Kerem", "Derya", "Onur"]
const LAST = ["Yılmaz", "Demir", "Kaya", "Arslan", "Çelik", "Şahin", "Aydın", "Öztürk", "Koç", "Polat"]
const CITY = ["İstanbul", "Ankara", "İzmir", "Bursa", "Antalya", "Konya"]
const STATUS = ["active", "invited", "suspended"] as const
const LABEL: Record<string, string> = { active: "Etkin", invited: "Davetli", suspended: "Askıda" }
const TONE: Record<string, "success" | "info" | "warn"> = { active: "success", invited: "info", suspended: "warn" }
const rnd = (i: number, m: number) => ((i * 2654435761) >>> 0) % m
const ROWS = Array.from({ length: 10_000 }, (_, i) => ({
  id: i + 1, name: `${FIRST[rnd(i, FIRST.length)]} ${LAST[rnd(i * 7 + 3, LAST.length)]}`, city: CITY[rnd(i * 13 + 5, CITY.length)],
  status: STATUS[rnd(i * 7 + 2, 10) < 6 ? 0 : rnd(i * 5 + 1, 10) < 6 ? 1 : 2], score: 1 + rnd(i * 11, 5), joined: Date.UTC(2024, 0, 1) + rnd(i * 17, 680) * 864e5,
}))

export function Members() {
  const invite = action("Davet gönder", async () => { await new Promise((r) => setTimeout(r, 300)) }, { icon: mail, success: "Davet gönderildi" })
  const suspend = action("Askıya al", async () => { await new Promise((r) => setTimeout(r, 300)) }, { icon: trash, danger: true, confirm: "Seçilenler askıya alınsın mı?", success: "Askıya alındı" })
  return <Table rows={ROWS} rowKey="id" virtual height={420} rowHeight={48} paging={false} selectable bulkActions={[invite, suspend]} filename="uyeler" caption="Üyeler"
    columns={[
      { key: "id", label: "#", align: "end", width: 64 },
      { key: "name", label: "Üye", width: 220, render: (r: typeof ROWS[number]) => <span sx={{ flex: "row", gap: 2 }}><Avatar name={r.name} size="sm" />{r.name}</span> },
      { key: "city", label: "Şehir", filter: "select", options: CITY },
      { key: "status", label: "Durum", filter: "select", options: STATUS.map((value) => ({ value, label: LABEL[value]! })), render: (r: typeof ROWS[number]) => <Badge tone={TONE[r.status]} dot>{LABEL[r.status]}</Badge> },
      { key: "score", label: "Puan", render: (r: typeof ROWS[number]) => <Rating value={r.score} readonly size="sm" /> },
      { key: "joined", label: "Katılım", format: "date" },
    ]} />
}

import { Table } from "march/table"
import { Button, Card, action } from "march/ui"
import { edit } from "march/icons"

// Table'ın özellikleri bir arada: rows (sinyal), columns (format, align, width, filter, render), rowKey, pageSize ve
// pageSizes, sort, search, selectable, rowActions, onRowClick, expand, empty, caption, label, layout (cards),
// toolbar ve toolbarEnd, exportable, rowClass, resizable, reorderable, onEdit (düzenlenebilir hücre)
type Task = { id: number; title: string; owner: string; points: number; done: boolean }
const make = (n: number): Task[] => Array.from({ length: n }, (_, i) => ({ id: i + 1, title: `Görev ${i + 1}`, owner: ["Ece", "Can", "Deniz"][i % 3]!, points: (i * 5) % 13 + 1, done: i % 4 === 0 }))

export function TableLab() {
  let $rows = make(12)
  let $clicked = "—"
  let $edits = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Button class="lab-add" size="sm" on:click={() => { $rows = make($rows.length + 1) }}>Görev ekle</Button>
      <Button class="lab-clear" size="sm" variant="ghost" on:click={() => { $rows = [] }}>Hepsini sil</Button>
      <span class="lab-state">Tıklanan: {$clicked} · düzenleme: {$edits}</span>
    </div>
    <Table class="lab-table" rows={() => $rows} rowKey="id" pageSize={5} pageSizes={[5, 10, 20]} sort={[{ key: "points", dir: "desc" }]} search
      selectable caption="Sprint görevleri" label="Görevler" toolbarEnd={<span sx={{ text: "xs", color: "muted" }}>{$rows.length} görev</span>}
      exportable resizable reorderable rowClass={(r: Task) => (r.done ? "is-done" : "")}
      empty="Görev yok, yeni bir tane ekle"
      onRowClick={(r: Task) => { $clicked = r.title }}
      expand={(r: Task) => <span sx={{ text: "sm", color: "muted" }}>{r.title}: {r.owner} · {r.points} puan</span>}
      rowActions={[action("Düzenle", (r: Task) => { $clicked = `düzenle ${r.title}` }, { icon: edit })]}
      onEdit={(r: Task, key: string, value: unknown) => { $edits++; $rows = $rows.map((x) => (x.id === r.id ? { ...x, [key]: value } : x)) }}
      columns={[
        { key: "title", label: "Görev", editable: true },
        { key: "owner", label: "Sahibi", filter: "select", options: ["Ece", "Can", "Deniz"] },
        { key: "points", label: "Puan", align: "end", format: "number", width: 90 },
        { key: "done", label: "Bitti", render: (r: Task) => (r.done ? "✓" : "") },
      ]} />
    <Card m:theme="night">
      <Table class="lab-cards" rows={() => $rows.slice(0, 3)} rowKey="id" layout="cards" toolbar={false} paging={false}
        columns={[{ key: "title", label: "Görev" }, { key: "points", label: "Puan", align: "end" }]} />
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { TableLab } from "./TableLab.tsx"

// TableLab'in testleri: kaydedince Testler sekmesinde çalışır
test("ilk sayfa beş satır; sayfa boyu ve başlık", () => {
  const s = renderTest(() => <TableLab />)
  const t = s.get(".lab-table")!
  expect(t.querySelectorAll("tbody tr").length).toBeGreaterThan(0)
  expect(t.querySelectorAll("tbody tr[data-key], tbody tr[aria-rowindex], tbody tr").length).toBeGreaterThan(4)
  expect(s.sees("Sprint görevleri")).toBe(true)
})

test("satıra tıklamak onRowClick'i çağırır", async () => {
  const s = renderTest(() => <TableLab />)
  const cells = Array.from(s.get(".lab-table")!.querySelectorAll("tbody td")) as HTMLElement[]
  const cell = cells.find((td: HTMLElement) => /^Görev \d+$/.test((td.textContent ?? "").trim()))!
  await s.click(cell)
  expect(s.get(".lab-state")!.textContent).toContain("Tıklanan: Görev")
})

test("veri boşalınca boş metni görünür", async () => {
  const s = renderTest(() => <TableLab />)
  await s.click(".lab-clear")
  expect(s.sees("Görev yok, yeni bir tane ekle")).toBe(true)
})

test("kart görünümü üç görevi çizer", () => {
  const s = renderTest(() => <TableLab />)
  expect(s.get(".lab-cards")!.textContent).toContain("Görev 1")
})
